create extension if not exists "pgcrypto";
create table if not exists public.users_profile (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade unique, full_name text, phone text, country text, target_country text, role text default 'user', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.program_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, full_name text, country_of_origin text, target_country text, education_level text, field_of_study text, gpa text, english_level text, budget_range text, preferred_city_type text, preferred_intake text, preferred_degree_level text, work_preference text, scholarship_need text, available_documents text, career_goal text, score integer, risk_level text, report_json jsonb, created_at timestamptz default now());
create table if not exists public.document_reviews (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, passport_status text, transcript_status text, grade_12_status text, national_exam_status text, cv_status text, motivation_letter_status text, recommendation_letter_status text, english_proof_status text, declaration_of_value_status text, cimea_status text, admission_status text, pre_enrollment_status text, sponsorship_letter_status text, birth_certificate_status text, police_clearance_status text, travel_insurance_status text, translation_status text, financial_docs_status text, other_docs_status text, score integer, risk_level text, report_json jsonb, created_at timestamptz default now());
create table if not exists public.financial_reviews (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, sponsor_name text, sponsor_relation text, bank_name text, statement_period text, currency text, opening_balance numeric, closing_balance numeric, average_balance numeric, large_deposits text, monthly_income_estimate numeric, monthly_expenses_estimate numeric, source_of_funds text, tuition_fee_amount numeric, living_cost_amount numeric, accommodation_proof text, sponsor_business_or_job_proof text, score integer, risk_level text, report_json jsonb, created_at timestamptz default now());
create table if not exists public.interview_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, target_country text, visa_type text, difficulty text, question text, answer text, score integer, feedback_json jsonb, created_at timestamptz default now());
create table if not exists public.final_reports (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, program_score integer, document_score integer, financial_score integer, interview_score integer, overall_score integer, risk_level text, report_json jsonb, created_at timestamptz default now());
create table if not exists public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, university_name text not null, program_name text, country text, intake text, application_status text default 'Researching', application_deadline date, portal_url text, application_fee numeric, scholarship_available boolean default false, notes text, priority text default 'Medium', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.document_vault_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, document_name text not null, category text, status text default 'Missing', expiry_date date, translation_needed boolean default false, legalization_needed boolean default false, linked_application uuid references public.applications(id) on delete set null, storage_path text, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null, description text, due_date date, priority text default 'Medium', status text default 'To Do', source_module text, linked_application uuid references public.applications(id) on delete set null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.consultant_review_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, report_id uuid references public.final_reports(id) on delete set null, request_type text, message text, contact_preference text, status text default 'New', created_at timestamptz default now());
create table if not exists public.uploads (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, file_name text, file_type text, module text, storage_path text, created_at timestamptz default now());
create table if not exists public.chat_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text default 'Brovi Scan Assistant', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.chat_messages (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.chat_sessions(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null, content text not null, created_at timestamptz default now());
create table if not exists public.user_settings (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade unique, theme text default 'system', email_notifications boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
insert into storage.buckets (id, name, public) values ('brovi-private-documents','brovi-private-documents',false) on conflict (id) do update set public=false;
